diff --git a/src/sanitize-svg.js b/src/sanitize-svg.js
new file mode 100644
index 0000000..5a2f9b7
--- /dev/null
+++ b/src/sanitize-svg.js
@@ -0,0 +1,78 @@
+const BLOCKED_ELEMENTS = {
+    animate: true,
+    animatecolor: true,
+    animatemotion: true,
+    animatetransform: true,
+    base: true,
+    embed: true,
+    foreignobject: true,
+    iframe: true,
+    link: true,
+    meta: true,
+    object: true,
+    script: true,
+    set: true
+};
+
+const URL_ATTRIBUTES = {
+    href: true,
+    src: true,
+    'xlink:href': true
+};
+
+const isUnsafeUrl = value => {
+    const normalized = value.replace(/[\u0000-\u001F\u007F\s]+/g, '').toLowerCase();
+    if (normalized.indexOf('javascript:') === 0) return true;
+    if (normalized.indexOf('vbscript:') === 0) return true;
+
+    /*
+     * Data URLs are needed for embedded bitmap assets in SVG costumes, but only
+     * image data should be allowed. Other data URL types can contain executable
+     * HTML/SVG content.
+     */
+    if (normalized.indexOf('data:') === 0 && normalized.indexOf('data:image/') !== 0) {
+        return true;
+    }
+
+    return false;
+};
+
+const isUnsafeStyle = value => {
+    const normalized = value.replace(/[\u0000-\u001F\u007F\s]+/g, '').toLowerCase();
+    return normalized.indexOf('expression(') !== -1 ||
+        normalized.indexOf('javascript:') !== -1 ||
+        normalized.indexOf('vbscript:') !== -1 ||
+        normalized.indexOf('data:text/html') !== -1 ||
+        normalized.indexOf('data:image/svg+xml') !== -1;
+};
+
+const sanitizeNode = node => {
+    const childNodes = Array.prototype.slice.call(node.childNodes);
+
+    for (const child of childNodes) {
+        if (child.nodeType !== Node.ELEMENT_NODE) continue;
+
+        const tagName = child.tagName.toLowerCase();
+        if (BLOCKED_ELEMENTS[tagName]) {
+            child.parentNode.removeChild(child);
+            continue;
+        }
+
+        const attributes = Array.prototype.slice.call(child.attributes);
+        for (const attribute of attributes) {
+            const name = attribute.name.toLowerCase();
+            const value = attribute.value;
+
+            if (name.indexOf('on') === 0 ||
+                    (URL_ATTRIBUTES[name] && isUnsafeUrl(value)) ||
+                    (name === 'style' && isUnsafeStyle(value))) {
+                child.removeAttribute(attribute.name);
+            }
+        }
+
+        sanitizeNode(child);
+    }
+};
+
+const sanitizeSvg = svgString => {
+    const parser = new DOMParser();
+    const documentElement = parser.parseFromString(svgString, 'image/svg+xml').documentElement;
+    sanitizeNode(documentElement);
+    return new XMLSerializer().serializeToString(documentElement);
+};
+
+module.exports = sanitizeSvg;
