+function forbidden(res) {
+  res.statusCode = 403;
+  res.end('Forbidden');
+}
+
+function getHost(value) {
+  if (!value || value === 'null') {
+    return;
+  }
+  var parsed = url.parse(value);
+  if (!parsed || !parsed.host || !/^https?:$/.test(parsed.protocol)) {
+    return;
+  }
+  return parsed.host.toLowerCase();
+}
+
+function isSameOrigin(req, value) {
+  var host = req.headers.host;
+  if (!host) {
+    return false;
+  }
+  return getHost(value) === host.toLowerCase();
+}
+
+module.exports = function(req, res, next) {
+  if (SAFE_METHODS[req.method]) {
+    return next();
+  }
+
+  /*
+   * State-changing Web UI/API requests must originate from the Web UI itself.
+   * This prevents a malicious site from driving a victim's browser to issue
+   * authenticated POST/PUT/DELETE requests to the local whistle instance.
+   */
+  var site = req.headers['sec-fetch-site'];
+  if (site && site !== 'same-origin' && site !== 'none') {
+    return forbidden(res);
+  }
+
+  var origin = req.headers.origin;
+  if (origin) {
+    return isSameOrigin(req, origin) ? next() : forbidden(res);
+  }
+
+  var referer = req.headers.referer;
+  if (referer) {
+    return isSameOrigin(req, referer) ? next() : forbidden(res);
+  }
+
+  next();
